
%% MPC TUNING 
clear; clc; close all; % remove variables from WS, clear CMD window, closes all open firgures


%% Paths
% Add all folders inside ./fcns to the MATLAB path.
% fcns contains functions such as getOmega, getPsi,...
addpath(genpath('./fcns'));

% Get root path of the BRCM toolbox/project.
BRCMRootPath = getBRCMRootPath();

% Global debug level used by BRCM
global g_debugLvl
g_debugLvl = 0;

%% Load saved building data
% Load building data generated by the generate-buildings script.
% tank_size is appended from the heat-demand calculation.
load('building4_data.mat')
%Ts_hrs = 0.25;

%% Water tank
V = tank_size.V;          % Tank volume from heat-demand sizing [m^3]
rho = 1000;               % Water density [kg/m^3]
cp = 4186;                % Specific heat capacity of water [J/(kg*K)]
Ts = Ts_hrs*3600;         % Sampling time [s]
b = Ts/(rho*cp*V);        % Tank temperature coefficient from energy balance

T0 = 45;                  % Initial tank temperature [°C]
COP = 3.53;               % Heat pump coefficient of performance


%% Expanded matrices
A_expand = blkdiag(A,1); % Add tank temperature as one extra state
Bu_expand = [Bu, zeros(nx,2); -b*Sq_m_zones', b, b]; % Add DHS/grid inputs and tank dynamics
Bv_expand = [Bv; zeros(1,nv)]; % Add zero disturbance effect on tank state


%% Simulation and prediction dimensions
n_times_hour = 4; % Number of timesteps per hour
hours = 24; % Number of hours per day
n_days = 30; % Number of simulation days
n_sim = hours*n_times_hour*n_days; % Total simulation timesteps

n_pred = 10; % MPC prediction horizon

ns_ = nz_zones*n_pred; % Total zone-temperature slack variables
ns_tank_ = n_pred; % Total tank slack variables

nx_ = nx*n_pred; % Total building states over horizon
nx_expand = size(A_expand,1); % Number of states including tank state
nx_expand_ = nx_expand*n_pred; % Total expanded states over horizon

nu_expand = size(Bu_expand,2); % Number of inputs including DHS and grid
nu_expand_ = nu_expand*n_pred; % Total expanded inputs over horizon

nv_expand = size(Bv_expand,2); % Number of disturbance inputs


%% WEATHER DATA
% allocate storage - solar radiation & ambient temperatures
SolRad_E = zeros(1,n_sim);
SolRad_S = zeros(1,n_sim);
SolRad_N = zeros(1,n_sim);

T_amb = zeros(1,n_sim);

for i = 1:n_sim

   % Synthetic solar radiation profile
   % The sine function creates a daily pattern
   % max(0, ...) makes sure radiation is never negative
   sine = max(0,(600*sin(2*pi*i/(24*4) + 3*pi/2)-100));

   % emulate diffrent angles of Sunlight due to Earth revolution
   % East-facing solar radiation.
   SolRad_E(i) = sine*0.7;  
   % South-facing solar radiation.
   SolRad_S(i) = sine;
   % North-facing solar radiation is set to zero.
   SolRad_N(i) = 0; % azimuth

   % Synthetic ambient temperature profile.
   % Temperature varies during the day using a sinusoidal function.
   T_amb(i) = -2.5 + 7.5*sin(2*pi*i/(24*4)+3*pi/2); 
end


%% Internal Gains
load('ihg_model.mat'); % load data from internal gains model/ occypancy profile

p_array = internalHeatGain.p_array; % occupancy profile from igh.mat
p_array = p_array(1:nz_zones,:); % Keep only the occupancy profiles for the modelled zones (5 rows, 96 timesteps (n_days = 1))

p_array = repmat(p_array,1,ceil(n_sim/96)); % repat matrix m x n times 
p_array = p_array(:,1:n_sim); % ensure only comlumns needed for simulation (for n_days = 1.5, etc)

Q_IG = 100*p_array; % 100 W scaling factor - scale occupancy profile to Internal Heat Gain
q_internalgain_m2 = zeros(nu,n_sim); % allocate storage for W/m^2

for i = 1:nu
   q_internalgain_m2(i,:) = Q_IG(i,:)./Sq_m_zones(i); % divide by sq m --> [W/m^2]
end

%% Price data
price_tbl = readtable('strompriser_30d_NO1.xlsx'); % Load grid electricity prices
price = price_tbl{:,2}; % Extract price column
price = price(:); % Ensure column vector
price_15min_grid = repelem(price,4); % Convert hourly prices to 15-min resolution

price_tbl_DHS = readtable('strompriser_30d_NO1_DHS.xlsx'); % Load DHS prices
price_DHS = price_tbl_DHS{:,2}; % Extract price column
price_DHS = price_DHS(:); % Ensure column vector
price_15min_DHS = repelem(price_DHS,4); % Convert hourly prices to 15-min resolution

%% Min/max radiator input bounds [W/m^2]

u_min = -g(1:2:end); % Extract lower radiator bounds from BRCM constraint vector
u_max =  g(2:2:end); % Extract upper radiator bounds from BRCM constraint vector

% Maximum heating power available from (DHS) and grid [W]
Qmax_DHS = 80000;
Qmax_grid = 80000;

% Extend input bounds with DHS and grid power variables
u_min_expand = [u_min; 0; 0]; 
u_max_expand = [u_max; Qmax_DHS; Qmax_grid];

%% Zone temperature limits [Celsius]
% Min/max allowed zone temperature
T_min = 15;
T_max = 30;
% Min/Max allowed water tank temperature

T_min_wt = 35;
T_max_wt = 55;

%% Prediction matrices
Omega = getOmega(A_expand,n_pred,'lti'); % Maps current state x0 to predicted states X
Psi   = getPsi(A_expand,Bu_expand,n_pred,'lti'); % Maps future control inputs u to predicted states X
Gamma = kron(eye(n_pred),Bv_expand); % Maps future disturbances v to predicted states X

%% Cost weights/parameters
% Weight on zone temperature tracking error.
% High value means the MPC strongly tries to keep temperatures near y_ref
Qy = 1000;


% Penalty on control input.
% Small R means heat usage is not strongly penalized - heat is cheap
R = 1e-6*eye(nu_expand);
R(nu+1,nu+1) = 1e-8; % DHS input penalty
R(nu+2,nu+2) = 1e-8; % grid input penalty

% quadratic penalty - help increase convexity of the quadratic part of the cost function --> increases curvature
quad_pen = 24; 


%% Initial conditions
%% Initial conditions
x0 = 18*ones(nx,1); % Initial building thermal states [°C]
x0_expanded = [x0; T0]; % Initial state including tank temperature

y_ref = 22*ones(nz_zones,1); % Zone temperature setpoint [°C]

T_tank_ref = 40; % Tank temperature reference [°C]
Q_tank = 10; % Weight on tank temperature tracking


%% Bounds
lb_x = -inf*ones(nx_expand*n_pred,1); % Lower bounds for predicted states
ub_x = inf*ones(nx_expand*n_pred,1); % Upper bounds for predicted states

for k = 1:n_pred
    tank_indices = (k-1)*nx_expand + nx_expand; % Tank state index at step k
    lb_x(tank_indices) = T_min_wt; % Lower tank temperature bound
    ub_x(tank_indices) = T_max_wt; % Upper tank temperature bound
end

lb_u = repmat(u_min_expand,n_pred,1); % Lower bounds for control inputs over the horizon
ub_u = repmat(u_max_expand,n_pred,1); % Upper bounds for control inputs over the horizon

% If the MPC cannot keep the temperatures within the limits, it can use sigma > 0 and pay a penalty in the cost function
% instead of making the optimization problem infeasible.
lb_sigma = zeros(nz_zones*n_pred,1); % Lower bounds for zone temperature slacks
ub_sigma = inf(nz_zones*n_pred,1); % Upper bounds for zone temperature slacks

lb_sigma_tank = zeros(n_pred,1); % Lower bounds for tank temp slacks
ub_sigma_tank = inf(n_pred,1); % Upper bounds for tank temp slacks

lb = [lb_x; lb_u; lb_sigma; lb_sigma_tank]; % Combined lower bounds
ub = [ub_x; ub_u; ub_sigma; ub_sigma_tank]; % Combined upper bounds



%% Output matrices
I = eye(nz_zones); % Identity matrix for the five zone temperatures

I_nz = zeros(nz_zones,nx_expand); % Output selection matrix for expanded state vector
I_nz(:,1:nz_zones) = I; % Select the first five states as zone temperatures

C = I_nz; % Output matrix, y = C*x

I_nz_ = kron(eye(n_pred), I_nz); % Output selection matrix over prediction horizon

%% Constraints
n_dec = length(lb); % Total number of decision variables
n_dec = nx_expand_ + nu_expand_ + ns_ + ns_tank_; % Total number of decision variables

A_tank = zeros(n_pred,n_dec); % Allocate tank constraint matrix
b_tank = zeros(n_pred,1); % Allocate tank constraint RHS

% Build tank inequality rows to be added to Aineq and bineq.
% This sets which radiator inputs and tank state are included in each row
for k = 1:n_pred
    u_idx = nx_expand_ + (k-1)*nu_expand + (1:nu); % Radiator input indices at step k
    tank_idx = (k-1)*nx_expand + nx_expand; % Tank temperature state index at step k

    A_tank(k,u_idx) = Sq_m_zones'; % Total radiator power from heat flux and zone areas
    A_tank(k,tank_idx) = -rho*cp*V/Ts; % Tank energy term
    b_tank(k) = -rho*cp*V*T_min_wt/Ts; % Minimum tank temperature limit
end


% Temperature inequality constraints with slack variables.
% Enforces T_min <= zone temperatures <= T_max over the prediction horizon.
Aineq_temp = [I_nz_, zeros(ns_,nu_expand_), -eye(ns_), zeros(ns_,n_pred);-I_nz_, zeros(ns_,nu_expand_), -eye(ns_), zeros(ns_,n_pred)];

bineq_temp = [T_max*ones(ns_,1);
              -T_min*ones(ns_,1)];

% Aineq * decision_vector <= bineq
Aineq = [Aineq_temp; A_tank]; % Combine temperature and tank inequality constraints
bineq = [bineq_temp; b_tank]; % Combine corresponding RHS side values


% Equality constraint for Gurobi. Prediction model: X = Omega*x0 + Psi*U + Gamma*V
% Rewritten as: X - Psi*U = Omega*x0 + Gamma*V
% Decision variables are [X; U; sigma; sigma_tank].
% The slack variables are not part of the system dynamics and therefore have zero columns in A_eq.
A_eq = [eye(nx_expand_), -Psi, zeros(nx_expand_,ns_), zeros(nx_expand_,n_pred)];

% Selects the tank temperature state in the cost function.
E_tank = diag([zeros(nx_expand-1,1); 1]);

% Hessian matrix for the quadratic cost function.
% Blocks: expanded states, control inputs, zone slacks and tank slacks.
% The state block penalizes zone temperature tracking and tank temperature tracking.
H = blkdiag(kron(eye(n_pred), C'*Qy*C + Q_tank*E_tank),kron(eye(n_pred), R),quad_pen*eye(ns_),1e6*eye(n_pred));

%% Allocate storage
nx_f = size(H,1);
f = zeros(nx_f,1);

x_array = zeros(nx_expand,n_sim+1);
y_array = zeros(nz_zones,n_sim+1);
u_array = zeros(nu_expand,n_sim);
v_array = zeros(nv_expand,n_sim);

x_array(:,1) = x0_expanded;
y_array(:,1) = C*x0_expanded;

z_end = nx_expand*n_pred;
u_end = z_end + nu_expand*n_pred;

%% Allocate storage

nx_f = size(H,1); % Number of optimization variables

f = zeros(nx_f,1); % Linear cost vector for Gurobi

x_array = zeros(nx_expand,n_sim+1); % Expanded state trajectory including tank state
y_array = zeros(nz_zones,n_sim+1); % Zone temperature trajectory
u_array = zeros(nu_expand,n_sim); % Applied control inputs: radiators, DHS and grid
v_array = zeros(nv_expand,n_sim); % Disturbance time series

% Initial conditions loaded into storage matrices
x_array(:,1) = x0_expanded;
y_array(:,1) = C*x0_expanded;

% End indices for predicted states and control inputs in the optimization vector
z_end = nx_expand*n_pred;
u_end = z_end + nu_expand*n_pred;




%% Fill disturbance array

% Assign weather disturbances to correct disturbance channels.
v_array(weather_idx.Tamb,:) = T_amb;
v_array(weather_idx.SolE,:) = SolRad_E;
v_array(weather_idx.SolS,:) = SolRad_S;
v_array(weather_idx.SolN,:) = SolRad_N;

% Assign internal gains from occupancy model to each zone.
v_array(ig_idx.zone1,:) = q_internalgain_m2(1,:);
v_array(ig_idx.zone2,:) = q_internalgain_m2(2,:);
v_array(ig_idx.zone3,:) = q_internalgain_m2(3,:);
v_array(ig_idx.zone4,:) = q_internalgain_m2(4,:);
v_array(ig_idx.zone5,:) = q_internalgain_m2(5,:);

%% DEFINE GUROBI
model.Q = sparse(H);
model.A = sparse([Aineq; A_eq]);
model.sense = [repmat('<',size(Aineq,1),1);repmat('=',size(A_eq,1),1)];
model.lb = lb;
model.ub = ub;

%% DEFINE GUROBI
% Quadratic cost matrix for Gurobi.
model.Q = sparse(H);

% Constraint matrix for Gurobi.
model.A = sparse([Aineq;A_eq]);% total restriction matrix 

% Constraint senses:
% '<' for temperature inequality constraints, '=' for equality constraints
model.sense =[repmat('<',size(Aineq,1),1);repmat('=',size(A_eq,1),1)];

% Lower and upper bounds for decision variables.
model.lb = lb; % set the lower bound (lb <= x <= ub)
model.ub = ub; % set the upper bound

%% MPC LOOP

for kk = 1:(n_sim - n_pred)

    v_end = min(kk + n_pred - 1, n_sim); % Last disturbance index within simulation length
    v_pred = v_array(:,kk:v_end); % Disturbance forecast over available horizon

    while size(v_pred,2) < n_pred % Pad forecast to full prediction horizon
        v_pred(:,end+1) = v_pred(:,end); % Repeat last disturbance value
    end

    % generating random forecast noise each iteration
    w_temp = 0.2*randn(1,size(v_pred,2));   % ambient temperature noise
    w_sol  = 15*randn(1,size(v_pred,2));    % solar radiation noise

    % add forecast noise
    v_pred(weather_idx.Tamb,:) = v_pred(weather_idx.Tamb,:) + w_temp;
    v_pred(weather_idx.SolE,:) = max(0, v_pred(weather_idx.SolE,:) + w_sol);
    v_pred(weather_idx.SolS,:) = max(0, v_pred(weather_idx.SolS,:) + w_sol);

    % vectorize after all edits
    v_pred = v_pred(:); % Stack forecast disturbances into one vector


    % Equality constraint update
    B_eq = Omega*x_array(:,kk) + Gamma*v_pred;

    price_DHS_h = price_15min_DHS(kk:kk+n_pred-1);
    price_grid_h = price_15min_grid(kk:kk+n_pred-1);

    f(:) = 0;

    for k = 1:n_pred % Update linear cost terms for each prediction step
        indices = (k-1)*nx_expand + (1:nx_expand); % Expanded state indices at step k
        f(indices) = -2*C'*Qy*y_ref; % Zone temperature tracking term

        tank_idx = (k-1)*nx_expand + nx_expand; % Tank temperature state index at step k
        f(tank_idx) = f(tank_idx) - 2*Q_tank*T_tank_ref; % Tank temperature tracking term

        u_indices = nx_expand*n_pred + (k-1)*nu_expand + (1:nu_expand); % Input indices at step k

        f(u_indices(nu+1)) = f(u_indices(nu+1)) + (price_DHS_h(k)*Ts_hrs)/1000; % DHS cost term
        f(u_indices(nu+2)) = f(u_indices(nu+2)) + price_grid_h(k)*Ts_hrs/(1000*COP); % Grid cost term
    end

 
    % GUROBI SOLVER
    model.obj = f; % Linear term
    model.rhs = [bineq; B_eq]; % Constraint RHS

    params.OutputFlag = 0;
    
    result = gurobi(model,params); % Solve Gurobi
    if ~isfield(result,'x') % stop if no solution is returned
        disp(result.status);
        return;
    end

    % Extract optimal control sequence
    x.opt = result.x; x.opt = result.x; % Optimal decision vector [X; U; sigma; sigma_tank]
    % Extract optimal control sequence
    u_opt = reshape(x.opt(z_end+1:u_end),nu_expand,n_pred);
    % Apply first control move
    u_array(:,kk) = u_opt(:,1);
    
    u_rooms(:,kk) = -b*Sq_m_zones' * u_array(1:5,kk); % Tank temperature decrease from radiator heat demand
    u_dhs(:,kk) = b*u_array(6,kk); % Tank temperature increase from DHS input
    u_grid(:,kk) = b*u_array(7,kk); % Tank temperature increase from grid input


    % State propagation
    x_array(:,kk+1) = A_expand*x_array(:,kk) + Bu_expand*u_array(:,kk) + Bv_expand*v_array(:,kk); % Simulate next expanded state
    y_array(:,kk+1) = C*x_array(:,kk+1); % Compute zone temperatures
end




%% Time vectors
Ts_days = Ts_hrs/24; % Sampling time [days]

N_state = size(x_array,2); % Number of stored state points
t_state_days = (0:N_state-1)' *Ts_days;
t_state_hours = t_state_days*24;

N_u = size(u_array,2); % Number of stored input points
t_u_days = (0:N_u-1)' *Ts_days;
t_u_hours = t_u_days*24;

%% Automatically choose time axis
if n_days == 1
    t_state_plot = t_state_hours;
    t_u_plot = t_u_hours;
    xlabel_text = 'Hour of day';
    x_limits = [0 24];
else
    t_state_plot = t_state_days;
    t_u_plot = t_u_days;
    xlabel_text = 'Days';
    x_limits = [0 max(t_u_days)];
end

%% Zone temperatures
y_plot = C*x_array;

figure;
plot(t_state_plot, y_plot', 'LineWidth',1.5)
hold on;
yline(22,'r--');

title('Zone temperature');
xlabel(xlabel_text);
ylabel('Temperature [°C]');

legend('Zone1','Zone2','Zone3','Zone4','Zone5','Reference','Location','best')

grid on;
xlim(x_limits)

if n_days == 1
    xticks(0:2:24)
    xticklabels({'00:00','02:00','04:00','06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00','22:00','24:00'})
end



%% Tank temperature
figure;
plot(t_state_plot, x_array(end,:)', 'LineWidth',1.5)
hold on;
yline(T_tank_ref,'r--');

title('Tank temperature');
xlabel(xlabel_text);
ylabel('Temperature [°C]');

legend('Tank temperature','Tank reference','Location','best')

grid on;
xlim(x_limits)

if n_days == 1
    xticks(0:2:24)
    xticklabels({'00:00','02:00','04:00','06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00','22:00','24:00'})
end

%% Total radiator power
Q_rad_tot = Sq_m_zones' * u_array(1:nu,:);
Q_rad_mean = mean(Q_rad_tot);

figure;
plot(t_u_plot, Q_rad_tot, 'LineWidth',1.5)
hold on;
yline(Q_rad_mean,'r--');

title('Total radiator power');
xlabel(xlabel_text);
ylabel('Q_{total} [W]');

legend('Total radiator power','Mean radiator power','Location','best')

grid on;
xlim(x_limits)

if n_days == 1
    xticks(0:2:24)
    xticklabels({'00:00','02:00','04:00','06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00','22:00','24:00'})
end

%% Energy sources
Q_dhs  = u_array(nu+1,:)';
Q_grid = u_array(nu+2,:)';

figure;
plot(t_u_plot, Q_dhs, 'LineWidth',1.5)
hold on;
plot(t_u_plot, Q_grid, 'LineWidth',1.5)

title('Energy sources');
xlabel(xlabel_text);
ylabel('Power [W]');

legend('DHS','Grid','Location','best')

grid on;
xlim(x_limits)

if n_days == 1
    xticks(0:2:24)
    xticklabels({'00:00','02:00','04:00','06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00','22:00','24:00'})
end

%% Cumulative cost
price_dhs  = price_15min_DHS(1:N_u);
price_grid = price_15min_grid(1:N_u);

cost_dhs  = price_dhs .* Q_dhs * Ts_hrs / 1000;
cost_grid = price_grid .* Q_grid * Ts_hrs / 1000;

cum_dhs  = cumsum(cost_dhs);
cum_grid = cumsum(cost_grid);
cum_tot  = cumsum(cost_dhs + cost_grid);

figure;
plot(t_u_plot, cum_dhs, 'LineWidth',1.5)
hold on;
plot(t_u_plot, cum_grid, 'LineWidth',1.5)
plot(t_u_plot, cum_tot, 'k', 'LineWidth',2)
title('Cumulative cost');
xlabel(xlabel_text);
ylabel('NOK');
legend('DHS','Grid','Total','Location','best')
grid on;
xlim(x_limits);

if n_days == 1
    xticks(0:2:24)
    xticklabels({'00:00','02:00','04:00','06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00','22:00','24:00'})
end

%% Summary
fprintf('Mean DHS:  %.2f W\n', mean(Q_dhs));
fprintf('Mean Grid: %.2f W\n', mean(Q_grid));
fprintf('Max DHS:   %.2f W\n', max(Q_dhs));
fprintf('Max Grid:  %.2f W\n', max(Q_grid));



%% Total radiator power
Q_rad_tot = Sq_m_zones' *u_array(1:nu,:);

fprintf('Max radiator power: %.2f W\n', max(Q_rad_tot));
fprintf('Min radiator power: %.2f W\n', min(Q_rad_tot));
fprintf('Mean radiator power: %.2f W\n', mean(Q_rad_tot));


%% Store MPC results and tuning parameters
mpc_results.mean_Q_dhs = mean(Q_dhs);
mpc_results.max_Q_dhs = max(Q_dhs);
mpc_results.min_Q_dhs = min(Q_dhs);
mpc_results.mean_Q_grid = mean(Q_grid);
mpc_results.max_Q_grid = max(Q_grid);
mpc_results.min_Q_grid = min(Q_grid);
mpc_results.mean_Q_rad = mean(Q_rad_tot);
mpc_results.max_Q_rad = max(Q_rad_tot);
mpc_results.min_Q_rad = min(Q_rad_tot);
mpc_results.total_DHS_energy_kWh = sum(Q_dhs)*Ts_hrs/1000;
mpc_results.total_grid_energy_kWh = sum(Q_grid)*Ts_hrs/1000;
mpc_results.total_radiator_energy_kWh = sum(Q_rad_tot)*Ts_hrs/1000;


mpc_tuning.Qy = Qy;
mpc_tuning.R = R;
mpc_tuning.R_dhs = R(nu+1,nu+1);
mpc_tuning.R_grid = R(nu+2,nu+2);
mpc_tuning.quad_pen = quad_pen;
mpc_tuning.n_pred = n_pred;


%save('building4_data2.mat','mpc_tuning','mpc_results','v_array','-append');





